async function submitLeadForm(event, setStatus, formType){
  event.preventDefault()
  const form = event.currentTarget
  const endpoint = import.meta.env.VITE_FORM_ENDPOINT
  if(!endpoint){
    setStatus({type:'error',message:'Form delivery is not configured. Add VITE_FORM_ENDPOINT to your .env.local file before accepting submissions.'})
    return
  }
  setStatus({type:'sending',message:'Sending…'})
  const payload = Object.fromEntries(new FormData(form).entries())
  payload.form_type = formType
  try{
    const response = await fetch(endpoint,{
      method:'POST',
      headers:{'Content-Type':'application/json','Accept':'application/json'},
      body:JSON.stringify(payload)
    })
    if(!response.ok) throw new Error(`Form endpoint returned ${response.status}`)
    form.reset()
    setStatus({type:'success',message:'Thank you. Your message has been sent.'})
  }catch(error){
    setStatus({type:'error',message:'We could not send your message. Please try again or call (888) 123 4560.'})
  }
}
function LeadFormFeedback({status}){
  if(!status) return null
  return <p className={`form-feedback form-${status.type}`} role="status" aria-live="polite">{status.message}</p>
}

function SmoothScroll(){
  useEffect(()=>{
    const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches
    if(reduceMotion) return
    const lenis = new Lenis({ duration:1.15, smoothWheel:true, wheelMultiplier:0.9, touchMultiplier:1.15 })
    lenis.on('scroll', ScrollTrigger.update)
    const tick = t => lenis.raf(t*1000)
    gsap.ticker.add(tick)
    gsap.ticker.lagSmoothing(0)
    const onAnchor = e => {
      const link = e.target.closest('a[href^="#"]')
      if(!link) return
      const target = document.querySelector(link.getAttribute('href'))
      if(target){ e.preventDefault(); lenis.scrollTo(target,{ offset:0, duration:1.25 }) }
    }
    const refresh = () => ScrollTrigger.refresh()
    const observer = typeof ResizeObserver !== 'undefined' ? new ResizeObserver(refresh) : null
    observer?.observe(document.body)
    window.addEventListener('load',refresh)
    window.addEventListener('resize',refresh)
    document.fonts?.ready?.then(refresh)
    document.addEventListener('click',onAnchor)
    return ()=>{ document.removeEventListener('click',onAnchor); window.removeEventListener('load',refresh); window.removeEventListener('resize',refresh); observer?.disconnect(); gsap.ticker.remove(tick); lenis.destroy() }
  },[])
  return null
}

function PageLoader(){
  const ref=useRef(null)
  useEffect(()=>{
    if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){ref.current?.remove();return}
    const ctx=gsap.context(()=>{
      gsap.timeline({defaults:{ease:'power3.inOut'},onComplete:()=>ref.current?.remove()})
        .fromTo('.loader-mark',{y:18,autoAlpha:0},{y:0,autoAlpha:1,duration:.55})
        .to('.loader-mark',{y:-12,autoAlpha:0,duration:.35,delay:.12})
        .to(ref.current,{yPercent:-100,duration:.85,ease:'power4.inOut'},'-=.05')
    },ref)
    return ()=>ctx.revert()
  },[])
  return <div className="page-loader" ref={ref} aria-hidden="true"><span className="loader-mark"><i>Z</i> zeneth</span></div>
}

function MotionDirector(){
  const root=useRef(null)
  useGSAP(()=>{
    if(window.matchMedia('(prefers-reduced-motion: reduce)').matches) return
    const q=(selector)=>gsap.utils.toArray(selector)
    const mobile=window.matchMedia('(max-width: 760px)').matches
    const reveal=(targets,trigger=targets,vars={})=>{
      const elements=q(targets)
      const triggerElement=q(trigger)[0]
      if(!elements.length || !triggerElement) return
      gsap.fromTo(elements,{y:mobile?22:34,autoAlpha:0},{y:0,autoAlpha:1,duration:mobile?.72:.9,ease:'power3.out',stagger:.11,scrollTrigger:{trigger:triggerElement,start:'top 86%',once:true},...vars})
    }
    reveal('.who-top > div','.who-top')
    reveal('.stat','.stat-panel',{stagger:.09})
    reveal('.challenge-head > *','.challenge-head')
    reveal('.approach-heading > *','.approach-heading')
    reveal('.approach-copy > *','.approach-content')
    reveal('.services-head > *','.services-head')
    reveal('.performance-top > *','.performance-top')
    reveal('.return-col','.return-bars',{y:24,stagger:.13})
    reveal('.global-heading > *','.global-heading')
    reveal('.regions span','.regions',{y:16,stagger:.08})
    reveal('.why-content > *','.why-content')
    reveal('.process-heading','.process-heading')
    reveal('.case-card','.case-grid',{y:48,stagger:.16})
    reveal('.testimonial-heading','.testimonial-heading')
    reveal('.cta-content > *','.cta-content',{y:28,stagger:.12})
    reveal('.footer-main > *','.footer-main',{y:28,stagger:.12})

    q('.hero-image img, .map-wrap img, .case-image > img:first-child, .process-photo img, .hero-dashboard').forEach(el=>{
      gsap.fromTo(el,{yPercent:mobile?-1.5:-3},{yPercent:mobile?1.5:3,ease:'none',scrollTrigger:{trigger:el.closest('section')||el,start:'top bottom',end:'bottom top',scrub:mobile?1:.7}})
    })
    q('.process-photo, .case-image').forEach(frame=>{
      gsap.fromTo(frame,{clipPath:'inset(0 0 100% 0)'},{clipPath:'inset(0 0 0% 0)',duration:1.15,ease:'power3.inOut',scrollTrigger:{trigger:frame,start:'top 88%',once:true}})
      const image=frame.querySelector('img')
      if(image) gsap.fromTo(image,{scale:1.12},{scale:1,duration:1.5,ease:'power3.out',scrollTrigger:{trigger:frame,start:'top 88%',once:true}})
    })
  })
  return null
}

function Header(){
  const [open,setOpen] = useState(false)
  const menuRef = useRef(null)
  const closeMenuRef = useRef(null)
  useEffect(()=>{
    document.body.classList.toggle('menu-open',open)
    const onKeyDown = event => { if(event.key==='Escape' && open) closeMenuRef.current?.() }
    document.addEventListener('keydown',onKeyDown)
    return ()=>{ document.body.classList.remove('menu-open'); document.removeEventListener('keydown',onKeyDown) }
  },[open])
  useGSAP(()=>{
    if(!open || !menuRef.current) return
    const tl=gsap.timeline({defaults:{ease:'power3.out'}})
    tl.fromTo(menuRef.current,{clipPath:'inset(0 0 100% 0)'},{clipPath:'inset(0 0 0% 0)',duration:.65})
      .fromTo(menuRef.current.querySelector('.menu-top'),{y:-18,autoAlpha:0},{y:0,autoAlpha:1,duration:.45},'-=.18')
      .fromTo(menuRef.current.querySelectorAll('.menu-links a'),{y:28,autoAlpha:0},{y:0,autoAlpha:1,duration:.55,stagger:.09},'-=.16')
      .fromTo(menuRef.current.querySelector('.menu-bottom'),{y:16,autoAlpha:0},{y:0,autoAlpha:1,duration:.45},'-=.28')
  },{dependencies:[open],scope:menuRef})
  const close = ()=>{
    if(!menuRef.current){setOpen(false);return}
    gsap.to(menuRef.current,{clipPath:'inset(0 0 100% 0)',duration:.42,ease:'power3.inOut',onComplete:()=>setOpen(false)})
  }
  closeMenuRef.current = close
  return <>
    <header className="site-header">
      <Link to="/" className="brand" aria-label="Zeneth home"><img src={assets.logoBlack} alt="Zeneth" /></Link>
      <div className="header-center"><span className="eyebrow">GET IN TOUCH</span><span className="header-phone">Call us today <b>(888) 123 4560</b></span></div>
      <div className="header-actions">
        <span className="social-mini" aria-hidden="true"><Instagram size={15}/><Linkedin size={15}/></span>
        <Link className="button button-dark header-cta" to="/contact">Book consultation <ArrowUpRight size={16}/></Link>
        <button className="menu-trigger" type="button" aria-expanded={open} aria-controls="site-navigation" aria-label={open?"Close navigation":"Open navigation"} onClick={()=>setOpen(true)}><span>MENU</span><MenuIcon size={18}/></button>
      </div>
    </header>
    {open && <div className="menu-overlay" id="site-navigation" ref={menuRef} role="dialog" aria-modal="true" aria-label="Site navigation">
      <div className="menu-top"><Link to="/" className="brand" onClick={close}><img src={assets.logoWhite} alt="Zeneth" /></Link><button className="close-menu" type="button" onClick={close}><span>CLOSE</span><X/></button></div>
      <div className="menu-body">
        <div className="menu-label">NAVIGATION</div>
        <nav className="menu-links">
          {[['Home','/'],['About','/about'],['Service','/service'],['Pricing','/pricing'],['Contact','/contact']].map(([n,p],i)=><Link key={n} to={p} onClick={close}><span className="menu-index">0{i+1}</span>{n}<ArrowUpRight/></Link>)}
        </nav>
        <div className="menu-utility"><span className="eyebrow">UTILITY PAGES</span><div><Link to="/style-guide" onClick={close}>Style guide</Link><Link to="/licenses" onClick={close}>Licenses</Link><Link to="/instructions" onClick={close}>Instructions</Link><Link to="/changelog" onClick={close}>Changelog</Link><Link to="/404" onClick={close}>404</Link><Link to="/401" onClick={close}>Password protected</Link></div></div>
        <div className="menu-bottom"><div><span className="eyebrow">CALL US TODAY</span><a href="tel:+18881234560">(888) 123 4560</a></div><div><span className="eyebrow">FOLLOW US</span><div className="social-row" aria-hidden="true"><span><Instagram/></span><span><Linkedin/></span><span><Facebook/></span></div></div></div>
      </div>
    </div>}
  </>
}

function Button({children='Explore us',href='#contact',dark=false,arrow=true}){return <a className={`button ${dark?'button-dark':'button-light'}`} href={href}>{children}{arrow&&<ArrowUpRight size={16}/>}</a>}
function SectionIntro({label,title,children,light=false}){return <div className={`section-intro ${light?'light':''}`}>{label&&<span className="eyebrow">{label}</span>}<h2>{title}</h2>{children&&<p>{children}</p>}</div>}
function Reveal({children,className=''}){const ref=useRef(null);useGSAP(()=>{gsap.fromTo(ref.current,{y:55,autoAlpha:0},{y:0,autoAlpha:1,duration:1,ease:'power3.out',scrollTrigger:{trigger:ref.current,start:'top 88%',once:true}})},{scope:ref});return <div ref={ref} className={className}>{children}</div>}
function ImageReveal({src,alt='',className=''}){const ref=useRef(null);useGSAP(()=>{const el=ref.current;gsap.fromTo(el,{clipPath:'inset(0 0 100% 0)'},{clipPath:'inset(0 0 0% 0)',duration:1.25,ease:'power3.inOut',scrollTrigger:{trigger:el,start:'top 88%',once:true}});gsap.fromTo(el.querySelector('img'),{scale:1.2},{scale:1,duration:1.5,ease:'power3.out',scrollTrigger:{trigger:el,start:'top 88%',once:true}})},{scope:ref});return <div ref={ref} className={`image-reveal ${className}`}><img src={src} alt={alt} loading="lazy"/></div>}
function Counter({value,suffix='',prefix=''}){const ref=useRef(null);useGSAP(()=>{const obj={n:0};gsap.to(obj,{n:value,duration:2,ease:'power2.out',scrollTrigger:{trigger:ref.current,start:'top 90%',once:true},onUpdate:()=>{if(ref.current)ref.current.textContent=prefix+Math.round(obj.n).toLocaleString()+suffix}})},{scope:ref});return <span ref={ref}>{prefix}0{suffix}</span>}

