function InnerMotion({children}){
 const root=useRef(null)
 useGSAP(()=>{
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return
  const scope=root.current
  gsap.fromTo(scope,{autoAlpha:0,y:12},{autoAlpha:1,y:0,duration:.65,ease:'power2.out'})
  scope.querySelectorAll('[data-reveal]').forEach(el=>gsap.fromTo(el,{y:34,autoAlpha:0},{y:0,autoAlpha:1,duration:.85,ease:'power3.out',scrollTrigger:{trigger:el,start:'top 88%',once:true}}))
  scope.querySelectorAll('.inner-image').forEach(frame=>{
   gsap.fromTo(frame,{clipPath:'inset(0 0 100% 0)'},{clipPath:'inset(0 0 0 0)',duration:1.1,ease:'power3.inOut',scrollTrigger:{trigger:frame,start:'top 88%',once:true}})
   const img=frame.querySelector('img'); if(img)gsap.fromTo(img,{scale:1.12},{scale:1,duration:1.35,ease:'power3.out',scrollTrigger:{trigger:frame,start:'top 88%',once:true}})
  })
 },{scope:root})
 return <div className="inner-motion-root" ref={root}>{children}</div>
}
