 <section className="team-section section-pad"><div className="section-shell"><SectionIntro label="MEET OUR TEAM" title="Experienced people. Thoughtful financial guidance."/><div className="team-grid">{[['Ethan Cole','Managing director',assets.teamEthan],['Maya Bennett','Brand strategist',assets.teamMaya],['Lucas Hayes','Finance manager',assets.teamLucas],['Sofia Carter','Marketing lead',assets.teamSofia]].map(([n,r,img])=><article key={n} data-reveal><div className="inner-image"><img src={img} alt={n}/></div><span>{r}</span><h3>{n}</h3></article>)}</div></div></section>
