const contactFaqGroups=[
 {label:'General questions',items:[['What is financial consulting and how can it help me?','Financial consulting provides expert guidance to help you make informed financial decisions, improve performance, manage risks, and achieve your long-term business or personal goals.'],['Why should I work with a financial consultant?','A financial consultant brings an objective perspective, financial expertise, and strategic insight to help you identify opportunities, solve complex challenges, and make confident decisions.'],['Who can benefit from financial consulting services?','Businesses, entrepreneurs, investors, and individuals can benefit from tailored financial guidance designed to improve financial performance, strengthen planning, and support sustainable growth.'],['What areas of finance can you help me with?','We provide support across financial planning, investment strategy, cash flow management, risk assessment, performance optimization, and strategic financial decision-making.'],['How does your financial consulting process work?','We begin by understanding your goals and financial position, then assess opportunities and challenges before developing a tailored strategy with clear, actionable recommendations.'],['How often should I review my financial plan?','Financial plans should be reviewed regularly and whenever major business, investment, income, or market changes occur to ensure your strategy remains aligned with your goals.'],['Why should I choose your financial consulting firm?','We combine strategic thinking, financial expertise, and personalized guidance to create practical solutions that support stronger decisions and sustainable long-term results.'],['How do you measure the success of a financial strategy?','Success is measured through relevant financial indicators such as profitability, cash flow, efficiency, investment performance, risk exposure, and progress toward defined objectives.']]},
 {label:'Services & Solutions',items:[['What financial consulting services do you offer?','We offer tailored financial planning, investment strategy, cash flow optimization, risk management, performance analysis, and strategic advisory services for long-term growth.'],['Can you create a customized financial strategy?','We offer tailored financial planning, investment strategy, cash flow optimization, risk management, performance analysis, and strategic advisory services to support your financial goals and long-term growth.'],['Do you provide investment planning and guidance?','We offer tailored financial planning, investment strategy, cash flow optimization, risk management, performance analysis, and strategic advisory services, designed to support your financial goals.'],['Can you help improve business cash flow?','We assess your cash flow structure, identify inefficiencies, and recommend practical strategies to improve liquidity, financial stability, and working capital management.'],['Do you provide financial risk management?','Yes. We identify potential financial risks and develop strategies to reduce exposure, strengthen resilience, and support more confident decision-making for long-term financial stability.'],['Can you help improve financial performance?','We analyze key financial metrics, identify performance gaps, and develop actionable recommendations to improve profitability, efficiency, and overall financial performance.'],['Do you offer long-term financial planning?','Yes. We create forward-looking financial strategies designed to support long-term objectives while adapting to changing market conditions and evolving financial priorities.'],['Can your services support growing businesses?','Absolutely. Our solutions can help growing businesses strengthen financial foundations, improve resource allocation, manage growth, and make better strategic investment decisions.']]},
 {label:'Process & Approach',items:[['What happens during the initial consultation?','We start by understanding your goals, current financial position, challenges, and priorities. This gives us the foundation to determine where strategic support can create the most value.'],['How do you assess my financial situation?','We review relevant financial information, performance indicators, cash flow, risks, and objectives to build a clear understanding of your current financial position and future financial needs.'],['How do you develop a financial strategy?','We combine financial analysis with your specific goals and priorities to create a practical strategy focused on measurable improvements, sustainable growth, and informed decision-making.'],['How involved will I be in the process?','You remain involved throughout the process. We maintain clear communication, explain our recommendations, and collaborate with you to ensure the strategy reflects your priorities.'],['How do you turn recommendations into action?','We review relevant financial information, performance indicators, cash flow, risks, and objectives to build a clear understanding of your current financial position, priorities, and opportunities.'],['How do you track financial progress?','We establish relevant performance indicators and regularly evaluate results against your objectives, allowing us to identify progress, challenges, and opportunities for improvement.'],['Can the strategy change as my needs evolve?','Yes. Financial strategies should evolve with changing goals, market conditions, business performance, and financial circumstances. We refine the approach when necessary.'],['How do you ensure the strategy delivers long-term value?','We focus on sustainable improvements rather than short-term gains, combining disciplined planning, measurable objectives, ongoing analysis, and strategic adjustments to support lasting results.']]}
]
function ContactPage(){const [contactStatus,setContactStatus]=useState(null),[newsletterStatus,setNewsletterStatus]=useState(null),[activeFaq,setActiveFaq]=useState(0);return <InnerFrame>
 <section className="contact-hero section-shell"><div className="contact-form-wrap" data-reveal><span className="eyebrow">GET IN TOUCH</span><h1>Transform your financial challenges into opportunities</h1><form className="contact-form" onSubmit={e=>submitLeadForm(e,setContactStatus,"contact")}><div className="form-grid"><label>Full name<input required name="name" placeholder="Your full name"/></label><label>Email<input required type="email" name="email" placeholder="Your email address"/></label><label>Phone<input name="phone" type="tel" placeholder="Your phone number"/></label><label>Address<input name="address" placeholder="Your address"/></label><label className="full">Subject<input required name="subject" placeholder="How can we help?"/></label></div><button className="button button-dark" type="submit">Submit now <ArrowUpRight/></button><LeadFormFeedback status={contactStatus}/></form></div><div className="contact-side"><div className="contact-person"><img src={assets.contactAvatar} alt="Marcus Whitfield"/><div><span className="eyebrow">YOUR POINT OF CONTACT</span><h3>Marcus Whitfield</h3><p>Senior advisor, New client intake</p></div></div><div className="office-info"><div><span className="eyebrow">OFFICE HOURS</span><p>Mon – Thu <b>8:00 am – 6:00 pm</b></p><p>Friday <b>8:00 am – 4:00 pm</b></p></div><div><span className="eyebrow">OFFICE</span><p>410 Sandtown, California 94001, USA</p></div></div></div></section>
 <section className="contact-faq section-pad"><div className="section-shell"><SectionIntro label="FAQ" title="Everything you need to know before making financial decisions"/><div className="faq-categories" role="tablist">{contactFaqGroups.map((group,i)=><button key={group.label} className={activeFaq===i?'active':''} role="tab" aria-selected={activeFaq===i} onClick={()=>setActiveFaq(i)}>{group.label}</button>)}</div><FAQList key={activeFaq} items={contactFaqGroups[activeFaq].items}/></div></section>
 <section className="newsletter-cta section-shell"><div data-reveal><span className="eyebrow">STAY CONNECTED</span><h2>Ready to take control of your financial success?</h2></div><form onSubmit={e=>submitLeadForm(e,setNewsletterStatus,"newsletter")}><label htmlFor="newsletter-email">Email Address</label><div><input id="newsletter-email" name="email" type="email" required placeholder="Enter your email"/><button type="submit" className="button button-dark" disabled={newsletterStatus?.type==="sending"}>Get started now <ArrowUpRight/></button></div><LeadFormFeedback status={newsletterStatus}/></form></section>
 </InnerFrame>}
